async function googleKeys(force=false){if(!force&&cachedKeys&&keysUntil>now())return cachedKeys;let res;try{res=await fetch('https://www.googleapis.com/oauth2/v3/certs',{redirect:'manual'});}catch{throw Error('keys unavailable');}if(!res.ok)throw Error('keys unavailable');let body;try{body=await res.json();}catch{throw Error('invalid keys');}if(!Array.isArray(body.keys))throw Error('invalid keys');cachedKeys=body.keys;keysUntil=now()+Math.min(3600,Number(res.headers.get('cache-control')?.match(/max-age=(\d+)/)?.[1]||60));return cachedKeys;}
export async function verifyGoogle(token,nonce,env,loadKeys=googleKeys){if(typeof token!=='string'||token.length>12000)throw Error('invalid credential');const [h,p,s,...extra]=token.split('.');if(!h||!p||!s||extra.length)throw Error('invalid credential');let head,c;try{head=json(h);c=json(p);}catch{throw Error('invalid credential');}if(head.alg!=='RS256'||typeof head.kid!=='string')throw Error('invalid algorithm');let jwk=(await loadKeys()).find(k=>k.kid===head.kid&&k.kty==='RSA');if(!jwk)jwk=(await loadKeys(true)).find(k=>k.kid===head.kid&&k.kty==='RSA');if(!jwk)throw Error('unknown key');let publicKey;try{publicKey=await crypto.subtle.importKey('jwk',{kty:'RSA',n:jwk.n,e:jwk.e,alg:'RS256',ext:true,key_ops:['verify']},{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']);}catch{throw Error('key import');}let valid;try{valid=await crypto.subtle.verify('RSASSA-PKCS1-v1_5',publicKey,unb64(s),enc.encode(h+'.'+p));}catch{throw Error('signature runtime');}if(!valid)throw Error('invalid signature');if(!['https://accounts.google.com','accounts.google.com'].includes(c.iss)||c.aud!==env.GOOGLE_CLIENT_ID||(c.azp&&c.azp!==env.GOOGLE_CLIENT_ID)||!Number.isSafeInteger(c.exp)||c.exp<=now()||!Number.isSafeInteger(c.iat)||c.iat>now()+60||c.iat<now()-600||(c.nbf!==undefined&&(!Number.isSafeInteger(c.nbf)||c.nbf>now())))throw Error('invalid claims');if(c.nonce!==nonce)throw Error('nonce');if(c.email_verified!==true||typeof c.sub!=='string'||!c.sub)throw Error('identity');if(!allow(c.email,env))throw Error('allowlist');if(!c.email.toLowerCase().endsWith('@gmail.com')&&!c.hd)throw Error('non-authoritative email');return c;}
const css='body{margin:0;background:#f8fafc;color:#17233c;font:16px/1.6 system-ui,sans-serif}main{max-width:920px;margin:auto;padding:3rem 1rem}header,article{background:white;border:1px solid #e2e8f0;border-radius:18px;padding:2rem}header{background:linear-gradient(120deg,#e0e7ff,#ccfbf1)}h1{font-size:clamp(2rem,5vw,3rem);margin:.2rem 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-top:1rem}small{color:#475569}button{padding:.6rem 1rem;background:#4338ca;color:white;border:0;border-radius:8px;cursor:pointer}';
